import {GRAPH_PRESETS,GRAPH_VIEWS,normalizeSelection,selectGraph} from './selection.mjs?v=20261014-3';
import {assessDirection,relationshipProfile,groupProfileEntries,PROFILE_GROUPS} from './profiles.mjs?v=20261014-3';
import {AC_GROUPS,classifyPrinciple,graphEligible,graphSlice} from './classification.mjs?v=20261014-3';
import {registerAtlasTools} from './browser-tools.mjs?v=20261014-3';
import {visibleRelations,closure,proofRecords,compare} from './engine.mjs?v=20261014-3';
import {renderGraph} from './graph.mjs?v=20261014-3';
const main=document.querySelector('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>s.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const link=(url,text)=>/^https?:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(text)}</a>`:esc(text);
const short={ac:'AC',wo:'Well-ordering',zorn:'Zorn',dc:'DC',ac_omega:'CC',pp:'PP',rpp:'RPP',wpp:'WPP',dual_csb:'CSB*',ac_wo_index:'ACᵂᴼ',nds_sets:'NDS',fb:'FB',bpi:'BPI',op:'OP',oep:'OEP',ac_finite_fibers:'AC(fin)',ac_omega_finite:'CC(fin)',ac_omega_countable:'CC(countable)',ultrafilter_lemma:'Ultrafilter lemma',kw:'KW',cuf:'CUF',cuc:'CUC',df_finite:'Dedekind infinitude',free_ultrafilter_omega:'Free ultrafilter on ω',tychonoff:'Tychonoff',tychonoff_hausdorff:'Hausdorff Tychonoff',propositional_compactness:'Prop. compactness',hahn_banach:'Hahn–Banach',baire_complete_metric:'Metric Baire',finite_antichains:'Finite antichains',svc:'SVC',svc_seed:'SVC(S)',svc_plus_seed:'SVC⁺(S)',kwp:'KWP',svc_wellorderable_seed:'SVC(W), W well-orderable',maximal_antichain:'Maximal antichains',kuratowski_maximal:'Kuratowski maximality',linear_orders_well_orderable:'LW',ac_2:'AC₂',ac_3:'AC₃',ac_4:'AC₄',ac_n:'ACₙ',ac_omega_n:'CCₙ',ac_countable_fibers:'AC(countable)',graph_coloring_compactness:'Gₙ (n ≥ 3)',graph_coloring_compactness_2:'G₂',infinite_hall_finite_fibers:'Hall (finite fibers)',no_amorphous:'No amorphous sets',some_free_ultrafilter:'Some free ultrafilter',algebraic_closure:'Algebraic closure',unique_algebraic_closure:'Closure uniqueness',mc:'Multiple choice',noetherian_acc_fg:'Noetherian equivalence',infinite_weakly_dedekind_infinite:'IWDI',sequential_continuity_metric:'Sequential continuity'};
let data,nodes,graph;
const state={node:'ac_omega',theory:'ZF',research:false,view:'choice',query:'',family:'',list:false,from:'pp',to:'ac',mobilePanel:'graph',acGroup:'',edgeKind:'all',focusArrows:false,customIds:[],includeAC:true,includeEquivalents:false,depth:0,wide:false,pickerQuery:''};
let currentSlice={ids:[],edges:[],isolated:[]};
let previousGraph=null;
const graphSettings=()=>({view:state.view,customIds:[...state.customIds],depth:state.depth,includeAC:state.includeAC,includeEquivalents:state.includeEquivalents,edgeKind:state.edgeKind,focusArrows:state.focusArrows});
const defaultGraphSettings=()=>({view:'choice',customIds:[],depth:0,includeAC:true,includeEquivalents:false,edgeKind:'all',focusArrows:false});
function setNeighbors(enabled){
 if(enabled&&state.view!=='neighbors'){
  previousGraph=graphSettings();state.view='neighbors';state.depth=Math.max(1,state.depth);state.edgeKind='all';state.focusArrows=false;
 }else if(!enabled&&state.view==='neighbors'){
  const restored=previousGraph||defaultGraphSettings();Object.assign(state,restored,{customIds:[...restored.customIds]});previousGraph=null;
 }
}
function chooseGraphView(view){
 if(view==='neighbors')setNeighbors(true);
 else{
  const displayed=[...currentSlice.ids],oldView=state.view,restoring=oldView==='neighbors'&&view===(previousGraph?.view||'choice');
  setNeighbors(false);
  if(!restoring){if(view==='custom'&&oldView!=='custom'){state.customIds=displayed;Object.assign(state,selectionFlags(displayed));}state.view=view;state.depth=0;}
  previousGraph=null;
 }
 refreshGraphOptions();
}
const label=id=>short[id]||nodes.get(id)?.name||id;
const relations=()=>visibleRelations(data,state.theory,state.research);
const status=r=>r.evidence_relations?'Two sourced directions':data.status_labels[r.status]||r.status||'Catalogue entry';
const symbol=r=>r.kind==='nonimplication'?(r.bidirectional?'↚↛':'↛'):r.kind==='equivalence'?'⇔':'⇒';
const claim=r=>!r.antecedents.length?`${state.theory} proves ${label(r.consequent)}`:`${r.antecedents.map(label).join(' ∧ ')} ${symbol(r)} ${label(r.consequent)}`;
const url=(id,options={})=>graphURL(id,options);
const badge=r=>r.layer==='recent'?'<span class="tag research">Recent research</span>':'';
const categoryTitle=c=>c==='choice'?'Types of choice':title(c);
const selectionFlags=ids=>({includeAC:ids.includes('ac'),includeEquivalents:ids.some(id=>id!=='ac'&&classification(nodes.get(id)).group==='equivalent')});
const categories=()=>[...new Set(data.principles.map(n=>n.category))].sort();
const familyOptions=value=>'<option value="">All families</option>'+categories().map(c=>`<option value="${c}" ${c===value?'selected':''}>${esc(categoryTitle(c))}</option>`).join('');
function button(r){return `<button class="relation-button" data-relation="${r.id}">${r.antecedents.length?r.antecedents.map(id=>esc(label(id))).join(' ∧ '):'Theorem'}<span class="relation-symbol ${r.kind}">${symbol(r)}</span>${esc(label(r.consequent))}<small>${esc(status(r))}${r.antecedents.length>1?' · joint hypotheses':''}</small></button>`}
function bindRelations(root=document){root.querySelectorAll('[data-relation]').forEach(b=>b.onclick=()=>showRelation(b.dataset.relation))}
function source(e){const s=e.source_id?data.sources[e.source_id]:e;return s?`<div class="source-item">${link(s.url,s.title||e.url)}${e.locator?`<small>${esc(e.locator)}</small>`:''}</div>`:''}
function evidence(e){const s=data.sources[e.source];return `<div class="source-item">${link(e.source_url||s?.url,s?.title||'Supporting source')}${s?.authors?`<small>${esc(s.authors.join(', '))}</small>`:''}<small>${esc(e.locator)}${e.status?` · ${esc(status(e))}`:''}</small>${e.principles?.length?`<small>Model facts: ${e.principles.map(id=>esc(label(id))).join(', ')}</small>`:''}${e.proof_note?`<p class="small">${esc(e.proof_note)}</p>`:''}</div>`}
function hiddenNotice(count){return count?`<div class="notice warm">${count} recent research relationship${count===1?' is':'s are'} hidden in this view. <button class="inline-button" data-show-research>Include recent research</button></div>`:''}
function enableResearch(){state.research=true;updateURL();explore()}
function classification(n){return classifyPrinciple(data,n,state.theory,true)}
function classificationTag(n){const c=classification(n);return `<span class="classification-badge ${c.group}">${esc(c.label)}</span>${c.layer==='recent'?'<span class="tag research">Preprint / recent research</span>':''}`}
function classificationPanel(n){const c=classification(n);return `<div class="classification-note"><strong>${AC_GROUPS.find(g=>g.id===c.group).title} · ${state.theory}</strong><p class="small">${esc(c.note||'See the cited source for the exact formulation and hypotheses.')}</p>${c.source_url?`<div class="source-item">${link(c.source_url,c.source_title||'AC-status reference')}<small>${esc(c.locator||'')}</small></div>`:''}${(c.supporting_sources||[]).map(e=>`<div class="source-item">${link(e.url,e.title||'Supporting source')}<small>${esc(e.locator)}</small></div>`).join('')}${c.review?`<p class="small muted">${esc(c.review)}</p>`:''}${c.proof?.map(button).join('')||''}${c.witnesses?.map(w=>`<p class="small"><a href="#model/${w.model.id}">${esc(w.model.name)}</a> witnesses failure of AC, assuming ${esc(w.model.assumptions)}.</p>${(w.factEvidence||[]).map(evidence).join('')}`).join('')||''}</div>`}
function definition(n){return `<p class="eyebrow">Principle · ${esc(label(n.id))}</p><h2>${esc(n.name)}</h2><div class="tag-row"><span class="tag theory">Definition: ${esc(n.base_theory)}</span><span class="tag">${esc(title(n.category))}</span>${classificationTag(n)}${n.id==='fb'?'<span class="tag research">Research-note terminology</span>':''}</div><div class="definition">${esc(n.definition)}</div>${n.definition.startsWith('C(')?'<p class="small muted"><strong>C(index, members)</strong> means every family with the indicated index set and nonempty members of the indicated type has a choice function. Countable means at most countable; no enumerations are supplied.</p>':''}${n.hypotheses?.length?`<div class="notice"><strong>Hypotheses and conventions</strong><ul>${n.hypotheses.map(h=>`<li>${esc(h)}</li>`).join('')}</ul></div>`:''}${n.notes?`<p class="small muted">${esc(n.notes)}</p>`:''}${Object.keys(n.parameters||{}).length?`<div class="notice">${Object.entries(n.parameters).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')}</div>`:''}${classificationPanel(n)}${n.history?`<details class="history-note"><summary>Historical background</summary><p class="small">${esc(n.history)}</p>${(n.history_evidence||[]).map(source).join('')}</details>`:''}`}
function graphURL(id=state.node,options={}){const s={...state,...options};const p=new URLSearchParams({node:id,view:s.view,theory:s.theory,research:s.research?'1':'0',ac:s.includeAC?'1':'0',equivalents:s.includeEquivalents?'1':'0',depth:String(s.depth),edges:s.edgeKind,arrows:s.focusArrows?'selected':'all'});if(s.view==='custom')p.set('nodes',s.customIds.join(','));return `#explore?${p}`}
function updateURL(){history.replaceState(null,'',graphURL());main.querySelectorAll('a[href^="#explore?"]').forEach(anchor=>{const id=new URLSearchParams(anchor.getAttribute('href').split('?')[1]).get('node');if(anchor.id!=='graph-permalink'&&nodes.has(id))anchor.href=url(id)});const permalink=document.querySelector('#graph-permalink');if(permalink)permalink.href=location.hash}
function select(id,focus=false,panel='detail'){if(!nodes.has(id))return;state.node=id;if(focus)setNeighbors(true);updateURL();detail();if(focus){refreshGraphOptions()}else document.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('selected',n.dataset.node===id));document.querySelectorAll('[data-principle]').forEach(b=>b.classList.toggle('selected',b.dataset.principle===id));if((state.view==='neighbors'||state.focusArrows)&&!focus){draw();renderPicker()}if(isPhone())setMobilePanel(panel)}
// Ordinary definition links behave like selecting a card, including returns
// from relationship pages. Keep the underlying graph snapshot across them.
main.addEventListener('click',event=>{
 if(event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
 const anchor=event.target.closest('a[href^="#explore?"]');if(!anchor||anchor.id==='graph-permalink')return;
 const href=anchor.getAttribute('href'),id=new URLSearchParams(href.split('?')[1]).get('node');
 if(nodes.has(id)){
  event.preventDefault();if(anchor.hasAttribute('data-include-research'))state.research=true;
  if(document.querySelector('.explore-layout'))select(id);
  else{state.node=id;updateURL();explore();syncPageNavigation('explore');window.scrollTo(0,0);}
 }
});
function syncPageNavigation(path){document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===path||a.dataset.page==='models'&&path.startsWith('model/')||a.dataset.page==='principles'&&(path.startsWith('principle/')||path.startsWith('relationships/'));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=`${title(path.split('/')[0])} · Weak Choice Atlas`}

const profileURL=id=>`#relationships/${encodeURIComponent(id)}?theory=${state.theory}&research=${state.research?'1':'0'}`;
function relationshipOverview(n,full=false){
 const profile=relationshipProfile(data,n.id,state.theory,state.research);
 const caption=(from,to,result)=>`${label(from)} ${result.status==='proved'?'⇒':result.status==='refuted'?'↛':'?⇒'} ${label(to)}`;
 const directions=e=>`<small><span class="direction-status ${e.reverse.status}">${esc(caption(e.id,n.id,e.reverse))}</span><span class="direction-status ${e.forward.status}">${esc(caption(n.id,e.id,e.forward))}</span></small>`;
 const pair=e=>`<details class="profile-pair" data-pair-other="${e.id}"><summary><strong>${esc(label(e.id))}</strong><span>${esc(e.name)}</span>${directions(e)}</summary><div class="profile-pair-evidence"></div></details>`;
 const groupRows=entries=>groupProfileEntries(data,entries,state.theory,state.research).map(group=>group.members.length===1?pair(group.representative):`<details class="profile-class" data-equivalence-class="${group.id}"><summary><strong>${esc(label(group.id))} and equivalents</strong><span>${group.members.length} formulations · expand to explore</span>${directions(group.representative)}</summary><div class="profile-class-members">${group.members.map(pair).join('')}</div></details>`).join('');
 return `<section class="relationship-overview ${full?'full-profile':'compact-profile'}" data-profile-for="${n.id}"><div class="profile-heading"><h3>All relationships · ${state.theory}</h3>${!full?`<a href="${profileURL(n.id)}">Open full view</a>`:''}</div><p class="small muted">Compared with all ${profile.total} other catalogue entries. Equivalent formulations share one expandable group. Implication lists include recorded paths through other principles. ${state.research?'Recent research is included with its source labels.':'Recent research is excluded.'}</p><label class="profile-search-label">Find another axiom<input type="search" class="profile-search" placeholder="Name or abbreviation…" aria-label="Search relationships"></label><p class="profile-search-count small muted" aria-live="polite"></p><div class="profile-groups">${PROFILE_GROUPS.filter(g=>profile.groups[g.id].length).map(g=>`<details class="profile-group" data-profile-group="${g.id}" ${full&&['equivalent','incoming','outgoing'].includes(g.id)?'open':''}><summary>${g.title}<span class="count" data-group-count>${groupProfileEntries(data,profile.groups[g.id],state.theory,state.research).length}</span></summary><p class="small muted">${g.description}</p><div class="profile-members">${groupRows(profile.groups[g.id])}</div></details>`).join('')}</div></section>`;
}
function bindProfile(root=document){
 root.querySelectorAll('[data-profile-for]').forEach(panel=>{
  const id=panel.dataset.profileFor,rows=[...panel.querySelectorAll('[data-pair-other]')];
  rows.forEach(row=>row.addEventListener('toggle',()=>{
   if(!row.open||row.dataset.loaded)return;row.dataset.loaded='1';const other=row.dataset.pairOther;
   const box=row.querySelector('.profile-pair-evidence');box.innerHTML=`<div class="link-row"><a href="${url(other)}">Definition of ${esc(label(other))}</a><a href="${profileURL(other)}">All relationships of ${esc(label(other))}</a></div>${direction(other,id)}${direction(id,other)}`;bindRelations(box);
  }));
  panel.querySelector('.profile-search').oninput=e=>{
   const q=e.target.value.trim().toLowerCase(),matched=new Set();
   rows.forEach(row=>{const n=nodes.get(row.dataset.pairOther);row.hidden=!!q&&!JSON.stringify([n.id,n.name,n.aliases,label(n.id)]).toLowerCase().includes(q);if(!row.hidden)matched.add(n.id)});
   panel.querySelectorAll('[data-equivalence-class]').forEach(group=>{group.hidden=![...group.querySelectorAll('[data-pair-other]')].some(row=>!row.hidden);if(q&&!group.hidden)group.open=true});
   panel.querySelectorAll('[data-profile-group]').forEach(group=>{const count=[...group.querySelector('.profile-members').children].filter(row=>!row.hidden).length;group.querySelector('[data-group-count]').textContent=count;group.hidden=!!q&&!count;if(q&&count)group.open=true});
   panel.querySelector('.profile-search-count').textContent=q?`${matched.size} matching principles`:'';
  };
 });
}
function relationshipPage(id){
 const n=nodes.get(id);if(!n)return notFound();state.node=id;
 main.innerHTML=`<section class="content-page profile-page"><div class="link-row"><a href="${url(id)}">Definition & graph</a><a href="#principles">Full catalogue</a></div><p class="eyebrow">Relationship profile</p><h1>${esc(n.name)}</h1><div class="definition">${esc(n.definition)}</div><div class="toolbar profile-controls">${controls()}</div><div id="detail">${relationshipOverview(n,true)}</div></section>`;
 bindProfile(main);bindControls(()=>{history.replaceState(null,'',profileURL(id));relationshipPage(id)});
}

function detail(){const n=nodes.get(state.node),el=document.querySelector('#detail');if(!el||!n)return;const rs=relations().filter(r=>r.antecedents.includes(n.id)||r.consequent===n.id);const hidden=!state.research?visibleRelations(data,state.theory,true).filter(r=>r.layer==='recent'&&(r.antecedents.includes(n.id)||r.consequent===n.id)).length:0;el.innerHTML=`${definition(n)}<div class="link-row"><button class="inline-button" id="focus-node">Focus graph</button><a href="${url(n.id)}">Permalink</a></div>${relationshipOverview(n)}<div class="detail-section"><h3>Direct relationships · ${state.theory}</h3>${rs.map(button).join('')||'<p class="small muted">No relationships recorded in this view.</p>'}${hiddenNotice(hidden)}</div><div class="detail-section"><h3>Definition sources</h3>${n.definition_evidence.map(source).join('')}</div>${n.aliases.length?`<div class="detail-section"><h3>Also searched as</h3><p class="small">${esc(n.aliases.join(' · '))}</p></div>`:''}${n.howard_rubin_reference?`<p class="small muted">Howard–Rubin form: ${esc(n.howard_rubin_reference)}</p>`:''}`;const focusButton=document.querySelector('#focus-node');if(focusButton)focusButton.onclick=()=>select(n.id,true,'graph');el.querySelectorAll('[data-show-research]').forEach(b=>b.onclick=enableResearch);bindRelations(el);bindProfile(el)}
function relationEvidence(r){const s=data.sources[r.source];return `<p class="eyebrow" style="margin-top:22px">${esc(r.kind)} · ${state.theory}</p><h2>${esc(claim(r))}</h2><div class="tag-row"><span class="tag">${esc(status(r))}</span>${badge(r)}</div>${r.antecedents.length>1?'<p class="notice" style="margin-top:18px">All displayed hypotheses are required together.</p>':''}${r.kind==='nonimplication'?`<div class="definition">A model satisfies ${r.antecedents.map(id=>esc(label(id))).join(' and ')} while ${esc(label(r.consequent))} fails.</div><p class="small"><strong>Consistency assumption:</strong> ${esc(r.consistency_assumption||r.assumptions||'See source')}</p><p class="small">${esc(r.proof_note)}</p><p class="small muted">This does not assert that the hypotheses imply the negation of the conclusion.</p>`:`<div class="definition">${esc(r.proof_note)}</div>`}<div class="detail-section"><h3>Evidence</h3>${r.source_url?`<div class="source-item">${link(r.source_url,s?.title||'Read the cited source')}<small>${esc(r.locator)}</small></div>`:'<p class="small">The elementary argument is included above. No claim of historical originality is made.</p>'}${r.readable_source_url?`<div class="source-item">${link(r.readable_source_url,'Read the later exposition')}<small>${esc(r.readable_locator)}</small></div>`:''}${r.also_source?`<div class="source-item">${link(r.also_source.url,'Related proof in the literature')}<small>${esc(r.also_source.locator)}</small></div>`:''}${(r.supporting_sources||[]).map(evidence).join('')}<p class="small muted">${esc(r.proof_access)}</p>${state.theory==='ZFA'&&r.base_review?`<p class="small muted">${esc(r.base_review)}</p>`:''}</div>${r.original_source?`<div class="detail-section"><h3>Original attribution</h3>${Object.entries(r.original_source).map(([k,v])=>`<p class="small"><strong>${esc(title(k))}:</strong> ${esc(v)}</p>`).join('')}</div>`:''}${r.model?`<div class="detail-section"><h3>Countermodel</h3><a href="#model/${r.model}">${esc(data.models.find(m=>m.id===r.model)?.name||r.model)}</a></div>`:''}<div class="detail-section"><h3>Principles in this statement</h3>${[...r.antecedents,r.consequent].map(id=>`<p class="small"><a href="${url(id)}">${esc(nodes.get(id)?.name||id)}</a></p>`).join('')}</div>`}
function showRelation(id){
 const r=data.relations.find(r=>r.id===id)||currentSlice.edges.find(r=>r.id===id);if(!r)return;
 const standalone=!document.querySelector('.explore-layout');
 if(!document.querySelector('#detail')){state.node=r.consequent;main.innerHTML='<section class="content-page narrow"><aside id="detail" aria-label="Proof evidence"></aside></section>'}
 const el=document.querySelector('#detail'),records=r.evidence_relations||[r];
 el.innerHTML=`<button class="inline-button" id="back-detail">Back to principle</button>${records.length>1?`<div class="notice"><strong>${r.kind==='nonimplication'?'Nonimplication in both directions':'Equivalent formulations'}</strong><p class="small">One graph edge combines the following statements. Each direction retains its own evidence${r.kind==='nonimplication'?' and may use a different countermodel':''}.</p></div>`:''}${records.map(record=>`<section class="edge-evidence" data-evidence-relation="${record.id}">${relationEvidence(record)}</section>`).join('')}`;
 document.querySelector('#back-detail').onclick=standalone?()=>route():detail;
 if(isPhone())setMobilePanel('detail');el.tabIndex=-1;el.focus({preventScroll:true});
 if(innerWidth<1190&&!isPhone())el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
}

function filter(q,f){return data.principles.filter(n=>(!f||n.category===f)&&`${n.name} ${n.id} ${label(n.id)} ${n.aliases.join(' ')} ${n.definition}`.toLowerCase().includes(q.trim().toLowerCase()))}
function groupButtons(active=''){return `<div class="ac-group-tabs" role="group" aria-label="Relationship to AC"><button class="ac-group-tab ${!active?'active':''}" data-ac-group="" aria-pressed="${!active}">All</button>${AC_GROUPS.map(g=>`<button class="ac-group-tab ${active===g.id?'active':''}" data-ac-group="${g.id}" aria-pressed="${active===g.id}">${g.title}</button>`).join('')}</div>`}
function list(){const category=document.querySelector('#catalog-category-note');if(category)category.innerHTML=categoryNote(state.family);const ns=filter(state.query,state.family).filter(n=>!state.acGroup||classification(n).group===state.acGroup);document.querySelector('#catalog-count').textContent=`${ns.length} principles & families`;document.querySelector('#catalog-list').innerHTML=AC_GROUPS.map(g=>{const members=ns.filter(n=>classification(n).group===g.id);return members.length?`<div class="catalog-group-heading">${g.title}<span class="catalog-group-count">${members.length}</span></div>${members.map(n=>`<button class="principle-link ${n.id===state.node?'selected':''}" data-principle="${n.id}"><strong>${esc(n.name)}</strong><span>${esc(classification(n).label)}</span></button>`).join('')}`:''}).join('')||'<p class="empty">No matching principles.</p>';document.querySelectorAll('[data-principle]').forEach(b=>b.onclick=()=>select(b.dataset.principle))}
function draw(){
 const focused=state.view==='neighbors';if(focused){state.edgeKind='all';state.focusArrows=false;state.depth=Math.max(1,state.depth);document.querySelector('#edge-kind').value='all';document.querySelector('#focus-arrows').checked=false;document.querySelector('#graph-depth').value=String(state.depth)}for(const id of ['edge-kind','focus-arrows','include-ac','include-equivalents']){const control=document.getElementById(id);if(control){control.disabled=focused;control.title=focused?'Focus shows every direct neighbor and relation type. Choose a topic or custom graph to filter.':''}}
 const rs=relations();currentSlice=selectGraph(data,rs,state);const {ids,edges,isolated}=currentSlice,host=document.querySelector('#graph');
 document.querySelector('#graph-title').textContent=state.view==='neighbors'?`Around ${label(state.node)}`:currentSlice.title;
 document.querySelector('#graph-count').textContent=`${ids.length} nodes · ${edges.length} relationships`;
 const hidden=!state.research?visibleRelations(data,state.theory,true).filter(r=>r.layer==='recent'&&ids.includes(r.consequent)&&r.antecedents.every(id=>ids.includes(id))).length:0;
 const notice=document.querySelector('#hidden-research');notice.innerHTML=hiddenNotice(hidden);notice.querySelectorAll('[data-show-research]').forEach(b=>b.onclick=enableResearch);
 document.querySelector('#selection-summary').textContent=`${ids.length} selected · ${isolated.length} with no displayed arrows. ${state.view==='neighbors'?'Complete direct neighborhood, including nonimplications and equivalent formulations. ':''}${state.focusArrows?'Showing arrows touching '+label(state.node)+'. ':''}${state.depth?'Includes '+state.depth+' connection step'+(state.depth===1?'':'s')+'.':'Exact selection; no automatic additions.'}`;
 document.querySelector('#small-graph-note').hidden=ids.length>=6;
 const finiteNote=document.querySelector('#finite-choice-note');if(finiteNote)finiteNote.hidden=!['choice','finitechoice'].includes(state.view);
 document.querySelector('.graph-controls').hidden=state.list;
 if(state.list){host.className='graph-list';host.innerHTML=edges.map(button).join('')||'<div class="empty">No relationships recorded in this selection.</div>';bindRelations(host);return}
 if(!ids.length){host.className='graph-list';host.innerHTML='<div class="empty"><h3>Choose axioms for your graph</h3><p>Use Choose axioms above, or select a topic.</p></div>';document.querySelector('.graph-controls').hidden=true;return}
 host.className='graph-canvas';graph=renderGraph(host,{ids,relations:edges,label,selected:state.node,focus:currentSlice.focus,focusRoles:currentSlice.focusRoles,onNode:id=>select(id),onEdge:showRelation});document.querySelector('#zoom-in').onclick=graph.zoomIn;document.querySelector('#zoom-out').onclick=graph.zoomOut;document.querySelector('#fit').onclick=graph.reset;
}
function categoryNote(category){const n=data.category_notes?.[category];return n?`<details class="finite-choice-note category-note"><summary>${esc(n.title)}</summary><p class="small">${esc(n.text)}</p>${n.bullets?.length?`<ul class="small">${n.bullets.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}${(n.details||[]).map(d=>`<details><summary>${esc(d.title)}</summary><p class="small">${esc(d.text)}</p></details>`).join('')}${(n.sources||[]).map(source).join('')}</details>`:''}
function finiteChoiceNote(){if(data.category_notes?.choice)return '<div id="finite-choice-note">'+categoryNote('choice')+'</div>';const n=data.finite_choice_note;return n?`<details class="finite-choice-note" id="finite-choice-note"><summary>${esc(n.title)}</summary><p class="small">${esc(n.text)}</p><p class="small"><strong>Examples:</strong> AC₂ ⇔ AC₄; AC₂ and AC₃ are incomparable. AC(fin) covers arbitrary finite fiber sizes and is stronger than each fixed-size instance.</p><p class="small">${link(n.source_url,'Mostowski’s original criterion')} · ${link(n.supporting_url,'Jech: the pure-ZF transfer')}<br>${esc(n.locator)}</p></details>`:''}
function graphOptions(){return `<details class="graph-builder" id="graph-builder"><summary>Choose axioms & graph settings</summary><p class="small muted">Start with a topic, then select exactly the axioms you want. A node without arrows means this view has no recorded relationship for it.</p><div class="graph-option-row"><label class="filter-check"><input type="checkbox" id="include-ac" ${state.includeAC?'checked':''}>Show AC</label><label class="filter-check"><input type="checkbox" id="include-equivalents" ${state.includeEquivalents?'checked':''}>Allow other AC equivalents</label><label>Connections<select id="graph-depth" aria-label="Expand graph connections"><option value="0" ${state.depth===0?'selected':''}>Only chosen axioms</option><option value="1" ${state.depth===1?'selected':''}>Add direct neighbors</option><option value="2" ${state.depth===2?'selected':''}>Add two steps of neighbors</option></select></label></div><label class="picker-search">Find an axiom to include<input type="search" id="node-picker-search" placeholder="CC, AC₂, ordering…" value="${esc(state.pickerQuery)}"></label><div class="graph-picker-actions"><button id="pick-topic">Use topic as my selection</button><button id="pick-all">Select all shown below</button><button id="pick-none">Clear selection</button></div><div id="node-picker" class="node-picker"></div><div class="graph-picker-actions"><button id="save-graph">Save this graph</button><button id="load-graph">Load saved graph</button><a id="graph-permalink" href="${esc(location.hash)}">Graph permalink</a></div><p id="graph-save-status" class="small muted" role="status"></p><details class="graph-rules"><summary>How is this graph chosen?</summary><p class="small">Topic views use explicit lists of related axioms. Your choices, the AC toggles and connection setting determine the nodes. ZF/ZFA, recent-research and arrow-type settings determine the eligible evidence. No axiom is removed just because it has no arrows. Previously omitted catalogue entries can be selected here.</p><p class="small">Solid arrows are recorded implications or equivalences; longer deductions can be found in each axiom’s relationship profile. Dashed arrows require a cited nonimplication. Missing arrows mean no displayed evidence, not independence. Choosing a node opens its details and preserves your graph. Enable Neighbors of the selected principle to follow each selection with its complete neighborhood; turn it off to restore your previous graph and settings. Stronger axioms appear above, consequences below, and incomparable axioms at the sides. Unknown comparisons have a separate labeled area. Focus includes both directions of nonimplication and every direct neighbor; use two steps for a wider view. Redundant implication arrows are omitted when a displayed path already proves them.</p></details></details><label class="filter-check arrow-focus-control"><input type="checkbox" id="neighbors-mode" ${state.view==='neighbors'?'checked':''}>Neighbors of the selected principle</label><label class="filter-check arrow-focus-control"><input type="checkbox" id="focus-arrows" ${state.focusArrows?'checked':''}>Only the selected axiom’s arrows · keep all nodes</label><p id="selection-summary" class="small muted" aria-live="polite"></p><p id="small-graph-note" class="notice" hidden>This selection has fewer than six axioms. Choose a broader topic or add neighbors in the graph settings.</p>`}
function renderPicker(){
 const q=state.pickerQuery.toLowerCase().trim(),selected=new Set(currentSlice.ids);
 const candidates=data.principles.filter(n=>!q||`${n.name} ${n.id} ${label(n.id)} ${n.aliases.join(' ')}`.toLowerCase().includes(q));
 document.querySelector('#node-picker').innerHTML=candidates.map(n=>`<label class="node-option"><input type="checkbox" data-pick-node="${n.id}" ${selected.has(n.id)?'checked':''}><span><strong>${esc(label(n.id))}</strong><small>${esc(n.name)}${classification(n).group==='equivalent'?' · AC equivalent':''}</small></span></label>`).join('')||'<p class="small muted">No matching axiom.</p>';
 document.querySelectorAll('[data-pick-node]').forEach(input=>input.onchange=()=>{
  const id=input.dataset.pickNode;state.customIds=[...currentSlice.ids];Object.assign(state,selectionFlags(state.customIds));state.view='custom';state.depth=0;
  if(input.checked){state.customIds.push(id);if(id==='ac')state.includeAC=true;else if(classification(nodes.get(id)).group==='equivalent')state.includeEquivalents=true}else state.customIds=state.customIds.filter(x=>x!==id);
  state.customIds=normalizeSelection(state.customIds,data);refreshGraphOptions();
 });
}
function refreshGraphOptions(){document.querySelector('#view').value=state.view;document.querySelector('#neighbors-mode').checked=state.view==='neighbors';document.querySelector('#graph-depth').value=String(state.depth);document.querySelector('#include-ac').checked=state.includeAC;document.querySelector('#include-equivalents').checked=state.includeEquivalents;document.querySelector('#edge-kind').value=state.edgeKind;document.querySelector('#focus-arrows').checked=state.focusArrows;draw();renderPicker();updateURL();document.querySelector('#graph-permalink').href=location.hash}
function bindGraphOptions(){
 document.querySelector('#neighbors-mode').onchange=e=>{setNeighbors(e.target.checked);refreshGraphOptions()};
 document.querySelector('#focus-arrows').onchange=e=>{state.focusArrows=e.target.checked;refreshGraphOptions()};
 document.querySelector('#node-picker-search').oninput=e=>{state.pickerQuery=e.target.value;renderPicker()};
 document.querySelector('#include-ac').onchange=e=>{state.includeAC=e.target.checked;if(state.view==='custom'&&state.includeAC&&!state.customIds.includes('ac'))state.customIds.push('ac');refreshGraphOptions()};
 document.querySelector('#include-equivalents').onchange=e=>{state.includeEquivalents=e.target.checked;refreshGraphOptions()};
 document.querySelector('#graph-depth').onchange=e=>{state.depth=Number(e.target.value);refreshGraphOptions()};
 document.querySelector('#pick-topic').onclick=()=>{state.customIds=[...currentSlice.ids];Object.assign(state,selectionFlags(state.customIds));state.view='custom';state.depth=0;refreshGraphOptions()};
 document.querySelector('#pick-none').onclick=()=>{state.customIds=[];state.view='custom';state.depth=0;refreshGraphOptions()};
 document.querySelector('#pick-all').onclick=()=>{const shown=[...document.querySelectorAll('[data-pick-node]')].map(e=>e.dataset.pickNode);state.customIds=normalizeSelection([...currentSlice.ids,...shown],data);state.view='custom';state.depth=0;state.includeAC=state.customIds.includes('ac');state.includeEquivalents=true;refreshGraphOptions()};
 document.querySelector('#save-graph').onclick=()=>{try{localStorage.setItem('weak-choice-custom-graph',JSON.stringify({ids:currentSlice.ids,theory:state.theory,research:state.research,...selectionFlags(currentSlice.ids),edgeKind:state.edgeKind,focusArrows:state.focusArrows,node:state.node}));document.querySelector('#graph-save-status').textContent='Saved on this device. The permalink also preserves your selection.'}catch{document.querySelector('#graph-save-status').textContent='Device storage is unavailable. Keep the graph permalink instead.'}};
 document.querySelector('#load-graph').onclick=()=>{try{const saved=JSON.parse(localStorage.getItem('weak-choice-custom-graph'));if(!saved||!Array.isArray(saved.ids))throw Error();state.customIds=normalizeSelection(saved.ids,data);state.view='custom';state.depth=0;state.includeAC=!!saved.includeAC;state.includeEquivalents=!!saved.includeEquivalents;state.theory=saved.theory==='ZFA'?'ZFA':'ZF';state.research=!!saved.research;state.focusArrows=!!saved.focusArrows;if(nodes.has(saved.node))state.node=saved.node;state.edgeKind=['all','nonimplication','implication'].includes(saved.edgeKind)?saved.edgeKind:'all';updateURL();explore();document.querySelector('#graph-builder').open=true;document.querySelector('#graph-save-status').textContent='Loaded your saved graph.'}catch{document.querySelector('#graph-save-status').textContent='No saved graph is available on this device yet.'}};
 renderPicker();
}
function controls(){return `<div class="toolbar-group"><span class="small muted">Base theory</span><div class="segmented" role="group" aria-label="Base theory"><button data-theory="ZF" class="${state.theory==='ZF'?'active':''}" aria-pressed="${state.theory==='ZF'}">ZF</button><button data-theory="ZFA" class="${state.theory==='ZFA'?'active':''}" aria-pressed="${state.theory==='ZFA'}">ZFA</button></div></div><label class="filter-check"><input id="research-toggle" type="checkbox" ${state.research?'checked':''}>Include recent research</label>`}
function bindControls(callback){document.querySelectorAll('[data-theory]').forEach(b=>b.onclick=()=>{state.theory=b.dataset.theory;callback()});document.querySelector('#research-toggle').onchange=e=>{state.research=e.target.checked;callback()}}
function comparisonForm(){const opts=id=>data.principles.map(n=>`<option value="${n.id}" ${n.id===id?'selected':''}>${esc(label(n.id))}</option>`).join('');return `<section class="compare-panel" aria-label="Compare two principles"><h2>Does one imply the other?</h2><div class="compare-inputs"><select id="compare-from" aria-label="First principle">${opts(state.from)}</select><span aria-hidden="true">⇄</span><select id="compare-to" aria-label="Second principle">${opts(state.to)}</select><button id="compare-button">Compare</button></div><div id="compare-result" class="compare-result" aria-live="polite"><span class="muted">Compare in ${state.theory}. Every answer shows its evidence.</span></div></section>`}
function direction(from,to){const r=assessDirection(data,from,to,state.theory,state.research);if(r.conflict)return '<p class="notice warm">Conflicting evidence needs review. No answer is asserted.</p>';if(r.proof!==null)return `<div class="comparison-direction"><strong>${esc(label(from))} ⇒ ${esc(label(to))}</strong><p class="small muted">${from===to?'The selections are identical.':r.proof.length===1?'A recorded implication or equivalence.':`Derived from ${r.proof.length} compatible records.`}</p>${r.proof.map(button).join('')}</div>`;if(r.witnesses.length)return `<div class="comparison-direction"><strong class="truth-false">${esc(label(from))} ↛ ${esc(label(to))}</strong>${r.witnesses.map(w=>`<p class="small"><a href="#model/${w.model.id}">${esc(w.model.name)}</a> is a witness, assuming ${esc(w.model.assumptions)}. ${badge(w.model)}</p>${(w.factEvidence||[]).map(evidence).join('')}${w.sourceProof.length||w.targetProof.length?`<details><summary class="small">Supporting implication paths</summary>${[...w.sourceProof,...w.targetProof].map(button).join('')}</details>`:''}`).join('')}</div>`;if(r.classificationFallback){const c=r.classificationFallback;return `<div class="comparison-direction"><strong>${esc(label(from))} ${r.status==='proved'?'⇒':'↛'} ${esc(label(to))}</strong><p class="small">${esc(c.note)}</p>${c.source_url?`<div class="source-item">${link(c.source_url,c.source_title||'Classification source')}<small>${esc(c.locator)}</small></div>`:''}${(c.supporting_sources||[]).map(e=>`<div class="source-item">${link(e.url,e.title)}<small>${esc(e.locator)}</small></div>`).join('')}${c.layer==='recent'?'<span class="tag research">Preprint / recent research</span>':''}</div>`}return `<div class="comparison-direction"><strong>${esc(label(from))} to ${esc(label(to))}: no result recorded</strong><p class="small muted">This is not a claim that the question is open.${!state.research?' Recent research is excluded from this view.':''}</p></div>`}
function runCompare(){state.from=document.querySelector('#compare-from').value;state.to=document.querySelector('#compare-to').value;const el=document.querySelector('#compare-result');el.innerHTML=direction(state.from,state.to)+(state.from===state.to?'':direction(state.to,state.from));bindRelations(el)}
const phoneLayout=matchMedia('(max-width: 740px)');
const isPhone=()=>phoneLayout.matches;
function setMobilePanel(panel,scroll=true){
 if(!['graph','catalog','detail'].includes(panel))return;
 state.mobilePanel=panel;
 const layout=document.querySelector('.explore-layout');if(!layout)return;
 layout.dataset.mobilePanel=panel;
 document.querySelectorAll('[data-mobile-panel-button]').forEach(b=>{const active=b.dataset.mobilePanelButton===panel;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
 if(panel==='graph')draw();
 if(scroll&&isPhone())document.querySelector(panel==='graph'?'#graph-panel':panel==='catalog'?'#catalog-panel':'#detail')?.scrollIntoView({block:'start'});
}
phoneLayout.addEventListener('change',()=>{if(document.querySelector('.explore-layout')){setMobilePanel(state.mobilePanel,false);if(!isPhone())draw()}});
function explore(){main.innerHTML=`<div class="page-heading"><div><p class="eyebrow">The landscape of weak choice</p><h1>Follow a principle. Find its proof.</h1><p>Explore implications, countermodels, and the questions between them.</p></div><span class="count">${data.principles.length} principles & families</span></div><div class="mobile-explore-tabs" role="group" aria-label="Explore sections"><button data-mobile-panel-button="graph" aria-controls="graph-panel">Graph</button><button data-mobile-panel-button="catalog" aria-controls="catalog-panel">Principles</button><button data-mobile-panel-button="detail" aria-controls="detail">Details</button></div><div class="explore-layout ${state.wide?'wide-graph':''}" data-mobile-panel="${state.mobilePanel}"><aside class="catalog-sidebar" id="catalog-panel" aria-label="Find a principle"><div class="search-wrap"><span class="search-icon" aria-hidden="true">⌕</span><input id="search" type="search" value="${esc(state.query)}" placeholder="Find a principle…" aria-label="Search principles"></div><select id="family" aria-label="Filter by family">${familyOptions(state.family)}</select><div id="catalog-category-note"></div><label class="small muted" for="ac-group-filter">Relationship to AC</label><select id="ac-group-filter" aria-label="Filter by relationship to AC"><option value="">All three groups</option>${AC_GROUPS.map(g=>`<option value="${g.id}" ${state.acGroup===g.id?'selected':''}>${g.title}</option>`).join('')}</select><div class="list-caption"><span id="catalog-count"></span></div><div id="catalog-list" class="catalog-list"></div><p class="small muted">Showing the selected entries. <a href="#principles">Browse the full catalogue</a>.</p></aside><section class="workspace" id="graph-panel" aria-label="Implication graph"><div class="toolbar">${controls()}</div><div class="toolbar"><select id="view" aria-label="Graph view">${GRAPH_VIEWS.map(([v,t])=>`<option value="${v}" ${v===state.view?'selected':''}>${t}</option>`).join('')}</select><select id="edge-kind" aria-label="Relationship types">${[['all','All arrows'],['nonimplication','Non-implications only'],['implication','Implications & equivalences']].map(([v,t])=>`<option value="${v}" ${state.edgeKind===v?'selected':''}>${t}</option>`).join('')}</select><button id="wide-graph" class="small" aria-pressed="${state.wide}">${state.wide?'Show principle list':'Wider graph'}</button><button id="graph-mode" class="small">${state.list?'Show graph':'List view'}</button></div>${state.theory==='ZFA'?'<p class="notice">Models with atoms and arguments valid in ZFA. Pure-ZF countermodels are not automatically transferred into this view.</p>':''}${state.research?'<p class="notice warm">Recent research retains its source and review status. It is not independently certified by this atlas.</p>':''}${graphOptions()}<div id="hidden-research" aria-live="polite"></div><div class="graph-box"><div class="graph-topline"><strong id="graph-title"></strong><span id="graph-count"></span></div><div id="graph" class="graph-canvas"></div><div class="graph-controls"><button id="zoom-out" aria-label="Zoom out">−</button><button id="fit" aria-label="Fit graph">Fit</button><button id="zoom-in" aria-label="Zoom in">+</button></div><div class="legend"><span><i></i>Implies</span><span><i class="nonimp"></i>Does not imply · two heads = both directions</span><span><i class="equiv"></i>Equivalent</span></div></div><p class="graph-note">Tap a node to read its details or an arrow for its evidence. Enable Neighbors of the selected principle to focus the graph. In neighbors mode: stronger above · weaker below · incomparable at the sides · unknown comparisons in a separate labeled area. Drag the background to move; use + and − to zoom. A dashed edge with two arrowheads means neither principle implies the other; click it for both proofs. A missing arrow is not a nonimplication. Use Choose axioms to include AC, its equivalents, or entries outside the default topics. Hover or focus an arrow to distinguish its route. Missing arrows are not claims of independence.</p>${finiteChoiceNote()}${comparisonForm()}</section><aside class="detail-panel" id="detail" aria-label="Selected principle and proof evidence"></aside></div>`;list();detail();draw();bindGraphOptions();document.querySelectorAll('[data-mobile-panel-button]').forEach(b=>b.onclick=()=>setMobilePanel(b.dataset.mobilePanelButton));setMobilePanel(state.mobilePanel,false);document.querySelector('#search').oninput=e=>{state.query=e.target.value;list()};document.querySelector('#family').onchange=e=>{state.family=e.target.value;list()};document.querySelector('#ac-group-filter').onchange=e=>{state.acGroup=e.target.value;list()};document.querySelector('#view').onchange=e=>chooseGraphView(e.target.value);document.querySelector('#edge-kind').onchange=e=>{state.edgeKind=e.target.value;refreshGraphOptions()};document.querySelector('#wide-graph').onclick=()=>{state.wide=!state.wide;explore()};document.querySelector('#graph-mode').onclick=()=>{state.list=!state.list;document.querySelector('#graph-mode').textContent=state.list?'Show graph':'List view';draw()};document.querySelector('#compare-button').onclick=runCompare;bindControls(()=>{updateURL();explore()})}
function principles(group=''){state.theory='ZF';let selectedGroup=group;main.innerHTML=`<section class="content-page"><p class="eyebrow">The catalogue · ZF</p><h1>How much choice does it take?</h1><p class="muted">Three groups, with exact hypotheses and evidence. AC equivalents can be included through the graph settings. A missing classification is not an open-problem claim.</p><div id="directory-groups">${groupButtons(selectedGroup)}</div><div class="content-toolbar"><input id="directory-search" type="search" placeholder="Search names, definitions, and aliases…" aria-label="Search the principle directory"><select id="directory-family" aria-label="Filter the principle directory">${familyOptions('')}</select></div><div id="directory-category-note"></div><div class="results-heading"><span id="directory-count" class="small muted"></span><a class="small" href="data.json" download>Download the catalogue</a></div><div id="directory-results"></div></section>`;const classify=n=>classifyPrinciple(data,n,'ZF',true);const update=()=>{document.querySelector('#directory-category-note').innerHTML=categoryNote(document.querySelector('#directory-family').value);const ns=filter(document.querySelector('#directory-search').value,document.querySelector('#directory-family').value).filter(n=>!selectedGroup||classify(n).group===selectedGroup);document.querySelector('#directory-count').textContent=`${ns.length} results`;document.querySelector('#directory-results').innerHTML=AC_GROUPS.filter(g=>!selectedGroup||selectedGroup===g.id).map(g=>{const members=ns.filter(n=>classify(n).group===g.id);if(!members.length)return '';return `<section class="ac-group-section" aria-label="${g.title}"><header><h2>${g.title} <span class="count">${members.length}</span></h2><p class="muted">${g.description}</p></header><div class="cards">${members.map(n=>{const c=classify(n);return `<article class="card"><p class="eyebrow">${esc(title(n.category))}</p><h3><a href="${url(n.id)}">${esc(n.name)}</a></h3><div class="definition">${esc(n.definition)}</div>${n.hypotheses?.length?`<details><summary>Hypotheses and conventions</summary><ul>${n.hypotheses.map(h=>`<li>${esc(h)}</li>`).join('')}</ul></details>`:''}<div class="tag-row"><span class="classification-badge ${c.group}">${esc(c.label)}</span>${c.layer==='recent'?'<span class="tag research">Preprint / recent research</span>':''}</div>${c.group==='unresolved'?`<p class="small muted">${esc(c.note)}</p>`:''}</article>`}).join('')||'<p class="empty">No matching principles in this group.</p>'}</div></section>`}).join('')};const bindGroups=()=>document.querySelectorAll('[data-ac-group]').forEach(b=>b.onclick=()=>{selectedGroup=b.dataset.acGroup;history.replaceState(null,'',`#principles${selectedGroup?'?group='+selectedGroup:''}`);document.querySelector('#directory-groups').innerHTML=groupButtons(selectedGroup);bindGroups();update()});document.querySelector('#directory-search').oninput=update;document.querySelector('#directory-family').onchange=update;bindGroups();update()}
function principlePage(id){const n=nodes.get(id);if(!n)return notFound();state.node=id;const rs=relations().filter(r=>r.antecedents.includes(id)||r.consequent===id);main.innerHTML=`<section class="content-page narrow"><a class="back-link" href="#principles">Principle catalogue</a><article>${definition(n)}<div class="link-row"><a href="${profileURL(n.id)}">Open all relationships</a></div>${relationshipOverview(n)}<div class="detail-section"><h3>Proofs and relationships · ${state.theory}</h3>${rs.map(button).join('')||'<p>See the cited definition and classification sources.</p>'}</div><div class="detail-section"><h3>Definition sources</h3>${n.definition_evidence.map(source).join('')}</div></article></section>`;bindRelations();bindProfile()}
function permutationConstruction(m){
 const c=m.permutation_construction;if(m.base!=='ZFA'||!c)return '';
 return `<section class="permutation-construction" aria-labelledby="construction-${m.id}"><div class="construction-heading"><p class="eyebrow">Permutation construction</p><h3 id="construction-${m.id}">The ingredients</h3><span class="tag theory">Ground model: ZFA + AC</span></div><dl class="construction-grid">${[['A','Atoms',c.atoms],['G','Group',c.group],['𝓕','Normal filter',c.normal_filter]].map(([symbol,name,text])=>`<div class="construction-part"><dt><span class="construction-symbol" aria-hidden="true">${symbol}</span><span>${name}</span></dt><dd>${esc(text)}</dd></div>`).join('')}</dl><div class="construction-foot"><p class="small"><strong>Allowed supports:</strong> ${esc(c.supports)}</p><p class="small muted">${esc(c.convention)}</p><p class="small">${link(c.source_url,'Construction reference')} · ${esc(c.locator)}</p></div></section>`;
}
function modelGuide(){const g=data.permutation_models_guide;return `<aside class="model-guide" aria-labelledby="model-guide-title"><p class="eyebrow">Before exploring the models</p><h2 id="model-guide-title">${esc(g.title)}</h2><p>${esc(g.text)}</p><p class="small">${esc(g.caveat)}</p><p class="small">${link(g.source_url,'The theorem and its hypotheses')} · ${esc(g.locator)}</p>${state.theory==='ZFA'?`<details><summary>How to read A, G and 𝓕</summary><p class="small">${esc(g.notation)}</p></details>`:''}</aside>`}
const modelsURL=()=>`#models?theory=${state.theory}&research=${state.research?'1':'0'}`;
function modelCard(m,full=false){
 const facts=[...m.true_ids.map(id=>({id,value:true})),...m.false_ids.map(id=>({id,value:false}))];
 const claims=(full||state.research||m.layer==='recent')?(m.additional_claims||[]):[];
 const followups=claims.flatMap(c=>[...(c.true_ids||[]).map(id=>({id,value:true,claim:c})),...(c.false_ids||[]).map(id=>({id,value:false,claim:c}))]).sort((a,b)=>Number(b.value)-Number(a.value));
 const row=f=>{const c=f.claim,authors=c?data.sources[c.source]?.authors:[];return `<tr data-principle-fact="${f.id}" ${c?'data-followup="true"':''}><td><a href="${url(f.id)}">${esc(label(f.id))}</a></td><td><span class="${f.value?'truth-true':'truth-false'}">${f.value?'Holds':'Fails'}</span>${c?`<small class="model-row-credit">${esc(authors?.join(', ')||'Follow-up research')}<span class="tag research">${esc(status(c))}</span>${link(c.source_url||data.sources[c.source]?.url,'Proof and source')}</small>`:''}</td></tr>`};
 return `<article class="card model-card" data-model="${m.id}"><p class="eyebrow">${m.base} · ${esc(status(m))}</p><h2>${full?esc(m.name):`<a href="#model/${m.id}">${esc(m.name)}</a>`}</h2>${badge(m)}<p>${esc(m.description)}</p><p class="small"><strong>Consistency assumption:</strong> ${esc(m.assumptions)}</p>${permutationConstruction(m)}<div class="table-wrap"><table><thead><tr><th>Principle</th><th>In this model</th></tr></thead><tbody>${facts.map(row).join('')}</tbody>${followups.length?`<tbody class="model-followups"><tr><th colspan="2" scope="rowgroup">Follow-up results</th></tr>${followups.map(row).join('')}</tbody>`:''}</table></div><p class="small muted" style="margin-top:14px">Other truth values are not recorded here. They are not assumed false.</p><div class="source-item">${link(m.source_url,'Read the construction and source')}<small>${esc(m.locator)}</small></div>${(m.property_evidence||[]).map(evidence).join('')}<p class="small muted">${esc(m.review)}</p>${full&&claims.length?`<details class="model-followup-evidence"><summary>Follow-up proof references</summary>${claims.map(c=>`<div>${evidence(c)}<p class="small">${esc(c.review)}</p></div>`).join('')}</details>`:''}</article>`;
}
function models(id){if(id){const m=data.models.find(m=>m.id===id);if(!m){notFound();return}state.theory=m.base;main.innerHTML=`<section class="content-page narrow"><a class="back-link" href="${modelsURL()}">All ${m.base} models</a>${modelCard(m,true)}</section>`;return}const ms=data.models.filter(m=>m.base===state.theory&&(state.research||m.layer!=='recent'));main.innerHTML=`<section class="content-page narrow"><p class="eyebrow">Countermodels</p><h1>Where principles come apart.</h1><p class="muted">Assumptions, constructions, and supported truth values.</p><div class="toolbar" style="margin:24px 0">${controls()}</div>${modelGuide()}<p class="small muted">${ms.length} ${state.theory} models in this view</p>${ms.map(m=>modelCard(m)).join('')||'<div class="card empty"><h2>No models recorded in this view.</h2></div>'}<p class="notice">A nonimplication is witnessed by a model satisfying the hypothesis and failing the conclusion. A model with atoms requires a justified transfer before establishing a ZF separation.</p></section>`;bindControls(()=>{history.replaceState(null,'',modelsURL());models()})}
function sources(){main.innerHTML=`<section class="content-page"><p class="eyebrow">Bibliography & proof access</p><h1>Keep the evidence in view.</h1><p class="muted">Definition references and proof sources have different jobs. Relationship panels give theorem locators and review levels.</p><div class="content-toolbar"><input id="source-search" type="search" placeholder="Search authors, titles, or references…" aria-label="Search sources"></div><div class="source-grid" id="source-results"></div></section>`;const update=()=>{const q=document.querySelector('#source-search').value.toLowerCase();document.querySelector('#source-results').innerHTML=Object.entries(data.sources).filter(([id,s])=>s.url&&JSON.stringify([id,s]).toLowerCase().includes(q)).map(([id,s])=>`<article class="card"><p class="eyebrow">${esc(s.source_type||'Reference')}</p><h2>${link(s.url,s.title)}</h2>${s.authors?`<p class="small">${esc(s.authors.join(', '))}</p>`:''}<p>${esc(s.role||s.access||'Referenced by catalogue records.')}</p>${s.version?`<p class="small muted">${esc(s.version)}</p>`:''}${s.review?`<p class="small muted">${esc(s.review)}</p>`:''}</article>`).join('')||'<p class="empty">No matching sources.</p>'};document.querySelector('#source-search').oninput=update;update()}
function about(){main.innerHTML=`<section class="content-page narrow prose"><p class="eyebrow">About the project</p><h1>A map you can follow back to the proof.</h1><p>I’m exploring weak forms of the axiom of choice and building this atlas as a place to organize the principles, proofs, and models along the way.</p><p>Created and maintained by <strong>Frederico Cançado</strong>. My partial research results live in ${link('https://github.com/frederico-cancado/AC-zoo-results','AC-zoo-results')}.</p><h2>Research articles</h2><p><a href="articles/algebraic-closures/">Algebraic closures: existence without uniqueness</a> · 14 October 2026. A preliminary preprint on existence, uniqueness, finite choice, and finite group torsors, with the full proof and supporting materials.</p><h2>How to read the atlas</h2><ul><li>Blue arrows are implications; bold orange dashed arrows with a ↛ badge are nonimplications; purple arrows are equivalences. AC is optional in graphs; other AC equivalents can be enabled in Choose axioms. Topic views are starting selections, and custom graphs are saved on this device or shared by permalink.</li><li>Every relationship belongs to a base theory. Switching ZF and ZFA changes the records and deductions.</li><li>“Source checked” means the statement was located in the cited source, not that the atlas independently verified the full proof.</li><li>“Elementary argument” includes an explanatory argument in the record.</li><li>Recent claims retain their attribution and limitations in the research layer.</li><li>The catalogue distinguishes AC equivalence, known non-equivalence, and unresolved classification. The last group explicitly separates documented open questions, parameter-dependent statements, and records still needing verification.</li></ul><h2>Complete axiom profiles</h2><p>Click a principle, then open All relationships for implications in both directions, equivalences, countermodels, and unanswered comparisons across the whole catalogue. Expand an entry to follow its proof path. Unknown / not recorded describes our current evidence, not a claim that the question is open. A pair can occur in an implication list and in the unknown list when only its reverse direction is unanswered.</p><h2>Coverage and deductions</h2><p>The initial catalogue has ${data.principles.length} records, ${data.relations.length} relationships and ${data.models.length} model descriptions. Family templates and equivalent formulations are not distinct mathematical strengths. More definitions have been entered than proof relationships.</p><p>The graph computes compatible implication paths. It does not chain nonimplications or drop joint hypotheses. Separating-model searches check that the same model supports the hypothesis and refutes the conclusion.</p><h2>Sources and predecessors</h2><p>Inspired by ${link('https://pi-base.org/','π-base')}. ${link('https://doi.org/10.1090/surv/059','Howard and Rubin’s Consequences of the Axiom of Choice')} and ${link('https://github.com/ioannad/jeffrey','Ioanna Dimitriou’s Choiceless Grapher')} are important predecessors. The atlas uses its own short summaries and links; it does not redistribute the Howard–Rubin files.</p><h2>Contribute a proof or correction</h2><p>Bring the exact formulation, base theory, and theorem or page reference. For a nonimplication, include the model and consistency assumptions. Original proofs and readable later expositions are welcome, with their roles identified.</p><p>${link('https://github.com/frederico-cancado/weak-choice-atlas/issues','Suggest a source or report a correction on GitHub')}.</p><h2>Open materials</h2><p>Original software is MIT-licensed. Original catalogue text and contributions are CC BY 4.0, with attribution to contributors. Linked papers retain their own terms.</p><div class="link-row"><a href="data.json" download>Download data</a><a href="LICENSE-MIT.txt">Software license</a><a href="LICENSE-CC-BY.txt">Content license</a><a href="#research">Recent research</a></div><p class="small muted" style="margin-top:30px">Initial edition · October 2026. Developed with AI assistance. Evidence and review levels are recorded individually.</p></section>`}
function recent(){main.innerHTML=`<section class="content-page narrow"><a class="back-link" href="#about">About the atlas</a><p class="eyebrow">Recent research</p><h1>New results, with their dependencies.</h1><p class="notice warm">These records are source-dependent or preliminary. Inclusion is not independent verification or a novelty claim.</p><article class="card model-card"><p class="eyebrow">Research article · 14 October 2026</p><h2><a href="articles/algebraic-closures/">Algebraic closures: existence without uniqueness</a></h2><div class="tag-row"><span class="tag research">Preliminary preprint</span><span class="tag theory">Pure ZF</span></div><p style="margin-top:15px">A symmetric model of ZF + DC in which every field has an algebraic closure, but uniqueness and finite choice fail. With existence assumed, uniqueness is equivalent to compactness for finite group torsors.</p><p class="small muted">Frederico Cançado · Not externally peer reviewed. The reverse implication from uniqueness to existence over pure ZF is unresolved in this work.</p><div class="link-row"><a href="articles/algebraic-closures/">Read the article &amp; supporting materials</a><a href="articles/algebraic-closures/algebraic_closures.pdf">PDF</a></div></article>${data.relations.filter(r=>r.layer==='recent').map(r=>`<article class="card model-card"><h2>${esc(claim(r))}</h2><span class="tag research">${esc(status(r))}</span><p style="margin-top:15px">${esc(r.proof_note)}</p><div class="source-item">${link(r.source_url,data.sources[r.source]?.title||'Source')}<small>${esc(r.locator)}</small></div>${(r.supporting_sources||[]).map(evidence).join('')}<p class="small muted">${esc(r.proof_access)}</p><a data-include-research href="${url(r.antecedents[0],{research:true})}">Explore with research included</a></article>`).join('')}<p class="notice">FB/NDS claims rely on additional properties of the construction. They are not entered as general PP ⇒ FB or PP ⇒ NDS implications.</p></section>`}
function notFound(){main.innerHTML='<section class="content-page"><h1>This page is not in the atlas.</h1><a href="#explore">Return to Explore</a></section>'}
function route(){const [path,query='']=(location.hash.slice(1)||'explore').split('?');const p=new URLSearchParams(query);if(path==='explore'){previousGraph=null;Object.assign(state,{view:'choice',node:'ac_omega',theory:'ZF',research:false,includeAC:true,includeEquivalents:false,depth:p.get('view')==='neighbors'?1:0,edgeKind:'all',focusArrows:false,customIds:[],list:false});if(nodes.has(p.get('node')))state.node=p.get('node');if(GRAPH_VIEWS.some(([id])=>id===p.get('view')))state.view=p.get('view');if(p.has('nodes')){state.customIds=normalizeSelection(p.get('nodes').split(','),data);state.view='custom'}if(p.has('arrows'))state.focusArrows=p.get('arrows')==='selected';if(p.has('ac'))state.includeAC=p.get('ac')==='1';if(p.has('equivalents'))state.includeEquivalents=p.get('equivalents')==='1';if(p.has('depth'))state.depth=[0,1,2].includes(Number(p.get('depth')))?Number(p.get('depth')):0;if(['all','nonimplication','implication'].includes(p.get('edges')))state.edgeKind=p.get('edges');if(['ZF','ZFA'].includes(p.get('theory')))state.theory=p.get('theory');if(p.has('research'))state.research=p.get('research')==='1';explore()}else if(path==='principles')principles(p.get('group')||'');else if(path.startsWith('principle/')||path.startsWith('relationships/')){if(['ZF','ZFA'].includes(p.get('theory')))state.theory=p.get('theory');if(p.has('research'))state.research=p.get('research')==='1';if(path.startsWith('relationships/'))relationshipPage(path.slice(14));else principlePage(path.slice(10))}else if(path==='models'){if(['ZF','ZFA'].includes(p.get('theory')))state.theory=p.get('theory');if(p.has('research'))state.research=p.get('research')==='1';models();}else if(path.startsWith('model/'))models(path.slice(6));else if(path==='sources')sources();else if(path==='about')about();else if(path==='research')recent();else if(path==='main'){explore();main.focus()}else notFound();syncPageNavigation(path)}
async function start(){try{const response=await fetch('./data.json',{cache:'no-cache'});if(!response.ok)throw Error('Catalogue unavailable');data=await response.json();registerAtlasTools(data);nodes=new Map(data.principles.map(n=>[n.id,n]));let i=0;for(const n of data.principles)for(const e of n.definition_evidence){if(!e.source_id&&e.url&&!Object.values(data.sources).some(s=>s.url===e.url))data.sources[`definition_${++i}`]={title:e.locator||e.url,url:e.url,role:'Definition reference; the principle record specifies its role.'}}window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0)});route()}catch(e){main.innerHTML='<div class="empty"><h1>The atlas could not load.</h1><p>Please reload. If this persists, check that data.json is available beside this page.</p><button id="retry">Try again</button></div>';document.querySelector('#retry').onclick=()=>location.reload();console.error(e)}}
start();
